def table(rows,widths=None):
 t=Table([[Paragraph(html.escape(str(x)),styles['BodyText']) for x in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e4eef0')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.5,colors.grey),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3)]));story.append(t);story.append(Spacer(1,8));md.extend([' | '.join(map(str,row)) for row in rows])
def page():story.append(PageBreak())
def fmt(name):
 s=secs[name]
 return name if s['type']=='W' else f"HSS {s['d']:g} x {s['d']:g} x "+{.125:'1/8',.188:'3/16',.25:'1/4',.313:'5/16',.375:'3/8',.5:'1/2',.625:'5/8'}[s['t']]
